const NUMBER_OF_SPARKLIES = 500;

function setup() {
	createCanvas(windowWidth, windowHeight);
	pixelDensity(1);
	frameRate(60);
	colorMode(HSB, 360, 100, 100, 100);
	cursor(CROSS);

window.simulatedMouseX = random(-1, 1) * 50 + width / 2;
window.simulatedMouseY = random(-1, 1) * 50 + height / 2;
}

function draw() {
	const halfWidth = width / 2;
	const halfHeight = height / 2;
	const minSize = max(width, height);

	const mDir = createVector(halfWidth - (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), halfHeight - (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))))
								.div(minSize / 2)
								.mult(5)
								.limit(5);

	// Draw previous frame with a bit of scaling and offset
	const lastFrame = get();
	blendMode(BLEND);
	background(0);
	push();
	translate(halfWidth, halfHeight);
	scale(1.02);
	translate(mDir.x, mDir.y);
	image(lastFrame, -halfWidth, -halfHeight);
	pop();

	// Fade out the trace
	background(0, random(6));

	// Draw sparkles
	noStroke();
	blendMode(ADD);
	const colr = (mDir.heading() / TWO_PI * 360 + 360) % 360;
	for (let j = NUMBER_OF_SPARKLIES; j--;) {
		stroke(colr, random(20, 80), 100);
		strokeWeight(random(1, 2));
		const p = p5.Vector.fromAngle(random(TWO_PI))
								.mult(random(random(random(random(max(width, height) * 0.3)))));
		point(p.x + halfWidth, p.y + halfHeight);
	}
}
